const PR44=[{label:"Ví dụ: Ba cách tính Fibonacci",input:"",code:"#include <iostream>\nusing namespace std;\n\nlong long nho[50];\n\nlong long fibNho(int n) {              // 1. từ trên xuống\n    if (n <= 1) return n;\n    if (nho[n] != 0) return nho[n];\n    return nho[n] = fibNho(n - 1) + fibNho(n - 2);\n}\n\nint main() {\n    int n = 10;\n    cout << fibNho(n) << \"\\n\";\n\n    long long f[50];                   // 2. từ dưới lên\n    f[0] = 0; f[1] = 1;\n    for (int i = 2; i <= n; i++) f[i] = f[i - 1] + f[i - 2];\n    cout << f[n] << \"\\n\";\n\n    long long a = 0, b = 1;            // 3. chỉ giữ hai ô cuối\n    for (int i = 2; i <= n; i++) {\n        long long c = a + b;\n        a = b;\n        b = c;\n    }\n    cout << b << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"f",ptr:["i"],range:["0","n"]},{type:"calls"}],py:{code:"nho = {}\n\ndef fib_nho(n):                        # 1. từ trên xuống\n    if n <= 1:\n        return n\n    if n not in nho:\n        nho[n] = fib_nho(n - 1) + fib_nho(n - 2)\n    return nho[n]\n\nn = 10\nprint(fib_nho(n))\n\nf = [0] * (n + 1)                      # 2. từ dưới lên\nf[1] = 1\nfor i in range(2, n + 1):\n    f[i] = f[i - 1] + f[i - 2]\nprint(f[n])\n\na, b = 0, 1                            # 3. chỉ giữ hai ô cuối\nfor i in range(2, n + 1):\n    a, b = b, a + b\nprint(b)",viz:[{type:"cells",of:"f",ptr:["i"]},{type:"calls"}]},cs:{code:"using System;\n\nclass Program\n{\n    static long[] nho = new long[50];\n\n    static long FibNho(int n)              // 1. từ trên xuống\n    {\n        if (n <= 1) return n;\n        if (nho[n] != 0) return nho[n];\n        return nho[n] = FibNho(n - 1) + FibNho(n - 2);\n    }\n\n    static void Main()\n    {\n        int n = 10;\n        Console.WriteLine(FibNho(n));\n\n        long[] f = new long[n + 1];            // 2. từ dưới lên\n        f[1] = 1;\n        for (int i = 2; i <= n; i++) f[i] = f[i - 1] + f[i - 2];\n        Console.WriteLine(f[n]);\n\n        long a = 0, b = 1;                     // 3. chỉ giữ hai ô cuối\n        for (int i = 2; i <= n; i++)\n        {\n            long c = a + b;\n            a = b;\n            b = c;\n        }\n        Console.WriteLine(b);\n    }\n}"}},{label:"Ví dụ: Đổi tiền ít đồng nhất",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int c[3] = {1, 3, 4};\n    int X = 10;\n    int best[11];\n    best[0] = 0;\n    for (int s = 1; s <= X; s++) {\n        best[s] = 1000000;\n        for (int j = 0; j < 3; j++)\n            if (c[j] <= s) best[s] = min(best[s], best[s - c[j]] + 1);   // đồng cuối là c[j]\n    }\n    cout << best[6] << \" \" << best[X] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"best",ptr:["s"]}],py:{code:"c = [1, 3, 4]\nX = 10\nbest = [0] * (X + 1)\nfor s in range(1, X + 1):\n    best[s] = 10**6\n    for x in c:\n        if x <= s:\n            best[s] = min(best[s], best[s - x] + 1)   # đồng cuối là x\nprint(best[6], best[X])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] c = { 1, 3, 4 };\n        int X = 10;\n        int[] best = new int[X + 1];\n        for (int s = 1; s <= X; s++)\n        {\n            best[s] = 1000000;\n            foreach (int x in c)\n                if (x <= s) best[s] = Math.Min(best[s], best[s - x] + 1);   // đồng cuối là x\n        }\n        Console.WriteLine(best[6] + \" \" + best[X]);\n    }\n}"}},{label:"Ví dụ: Đếm số cách đổi tiền",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int c[3] = {1, 2, 5};\n    int X = 5;\n    int cach[6] = {1, 0, 0, 0, 0, 0};  // cach[0] = 1: không dùng đồng nào\n    for (int j = 0; j < 3; j++)        // mệnh giá ở ngoài\n        for (int s = c[j]; s <= X; s++)\n            cach[s] += cach[s - c[j]];\n    cout << cach[X] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"cach",ptr:["s"]}],py:{code:"c = [1, 2, 5]\nX = 5\ncach = [1] + [0] * X                   # cach[0] = 1: không dùng đồng nào\nfor x in c:                            # mệnh giá ở ngoài\n    for s in range(x, X + 1):\n        cach[s] += cach[s - x]\nprint(cach[X])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] c = { 1, 2, 5 };\n        int X = 5;\n        int[] cach = new int[X + 1];\n        cach[0] = 1;                           // không dùng đồng nào\n        foreach (int x in c)                   // mệnh giá ở ngoài\n            for (int s = x; s <= X; s++)\n                cach[s] += cach[s - x];\n        Console.WriteLine(cach[X]);\n    }\n}"}},{label:"Ví dụ: Không hái hai cây kề nhau",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[7] = {2, 7, 9, 3, 1, 8, 4};\n    // dp[i] = max(dp[i-1], dp[i-2] + a[i]); chỉ cần hai giá trị trước\n    int truoc2 = 0, truoc1 = 0;\n    for (int i = 0; i < 7; i++) {\n        int moi = max(truoc1, truoc2 + a[i]);   // bỏ nhà i, hoặc lấy nhà i\n        truoc2 = truoc1;\n        truoc1 = moi;\n    }\n    cout << truoc1 << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"vars",names:["truoc2","truoc1"]}],py:{code:"a = [2, 7, 9, 3, 1, 8, 4]\n# dp[i] = max(dp[i-1], dp[i-2] + a[i]); chỉ cần hai giá trị trước\ntruoc2 = truoc1 = 0\nfor i in range(len(a)):\n    moi = max(truoc1, truoc2 + a[i])   # bỏ cây i, hoặc hái cây i\n    truoc2, truoc1 = truoc1, moi\nprint(truoc1)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 2, 7, 9, 3, 1, 8, 4 };\n        // dp[i] = max(dp[i-1], dp[i-2] + a[i]); chỉ cần hai giá trị trước\n        int truoc2 = 0, truoc1 = 0;\n        for (int i = 0; i < a.Length; i++)\n        {\n            int moi = Math.Max(truoc1, truoc2 + a[i]);   // bỏ cây i, hoặc hái cây i\n            truoc2 = truoc1;\n            truoc1 = moi;\n        }\n        Console.WriteLine(truoc1);\n    }\n}"}},{label:"Lỗi: đảo thứ tự vòng lặp khi đếm cách",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int c[3] = {1, 2, 5};\n    int X = 5;\n    int cach[6] = {1, 0, 0, 0, 0, 0};\n    for (int s = 1; s <= X; s++)       // SAI cho bài tổ hợp: số tiền ở ngoài\n        for (int j = 0; j < 3; j++)\n            if (c[j] <= s) cach[s] += cach[s - c[j]];\n    cout << cach[X] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"cach",ptr:["s"]}],py:{code:"c = [1, 2, 5]\nX = 5\ncach = [1] + [0] * X\nfor s in range(1, X + 1):              # SAI cho bài tổ hợp: số tiền ở ngoài\n    for x in c:\n        if x <= s:\n            cach[s] += cach[s - x]\nprint(cach[X])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] c = { 1, 2, 5 };\n        int X = 5;\n        int[] cach = new int[X + 1];\n        cach[0] = 1;\n        for (int s = 1; s <= X; s++)           // SAI cho bài tổ hợp: số tiền ở ngoài\n            foreach (int x in c)\n                if (x <= s) cach[s] += cach[s - x];\n        Console.WriteLine(cach[X]);\n    }\n}"}}];
